import Core

namespace Zoo.Rhino


def retention (baseline after : Float) : Float :=
  if baseline == 0.0 then (if after == 0.0 then 1.0 else 0.0) else clip01 (after/baseline)
def shockAmplification (performance structural magnitude : Float) : Float :=
  (1.0-(0.5*performance+0.5*structural))/maxF 0.000000001 magnitude
def gracefulFailure (invariants performance : Float) : Float := clip01 (0.6*invariants+0.4*performance)
/-- Domain invariants stay caller-supplied predicates, never assumed true. -/
def Survives {α : Type} (state : α) (invariants : List (α → Prop)) : Prop :=
  ∀ p ∈ invariants, p state
theorem survives_selected_invariant {α : Type} (s : α) (ps : List (α → Prop))
    (p : α → Prop) (h : Survives s ps) (hp : p ∈ ps) : p s := h p hp


end Zoo.Rhino

Whale.lean:
import Core

namespace Zoo.Whale


def cumulativeDeviation (xs : List Float) (baseline : Float) : Float :=
  meanF (xs.map (fun x => absF (x-baseline)))
def historyGap (xs : List Float) (window : Nat) : Float :=
  if xs.isEmpty then 0.0 else absF (meanF (xs.drop (xs.length-window))-meanF xs)
def stability (drift cumulative gap memory driftScale deviationScale gapScale : Float) : Float :=
  pos (1.0-(0.30*minF 1.0 (absF drift*driftScale)+0.25*minF 1.0 (cumulative*deviationScale)+
    0.25*minF 1.0 (gap*gapScale)+0.20*minF 1.0 (memory*gapScale)))
theorem empty_history_zero_gap (w : Nat) : historyGap [] w = 0.0 := by simp [historyGap]


end Zoo.Whale
